236	/// Actions that are blocked on another internal action of the guest, such as a pipe communication,
237	/// or are blocked on external conditions such as a network request.  These cannot consume a logical
238	/// turn until a matching unblocking action is ready.
239	///
240	/// This structure will NOT include blocking operations that are implemented via polling.
241	/// See NOTE [Blocking Syscalls via Internal Polling] in this folder.
242	#[derive(Debug, Clone, Default)]
243	pub struct BlockedPool {
244	    /// BLOCKED futex transactions, waiting for wakers. Multiple threads may be blocked on
245	    /// the same futex.
246	    ///
247	    /// INVARIANT: because Futexes aren't currently modeled with `ResourceID`, a thread
248	    /// waiting on a futex will have a request filled in `next_turns` but for zero resources.
249	    pub futex_waiters: HashMap<FutexID, Vec<FutexWaiter>>,
250	
251	    /// Futex waiters whose deadlines expired and must receive `ETIMEDOUT` when scheduled.
252	    /// Timed-out waiters are removed from `futex_waiters` before entering the run queue.
253	    pub timed_out_futex_waiters: HashSet<DetTid>,
254	
255	    /// Threads whose next event is waiting on a point in time to proceed.
256	    ///
257	    /// This is sorted by soonest time of occurrence.
258	    /// NOTE: futex waiters will ALSO appear in here if they have timeouts.
259	    pub timed_waiters: TimedEvents,
260	
261	    /// Threads parked until a matching child process exits logically.
262	    pub child_waiters: BTreeMap<DetTid, (DetPid, ChildWaitSpec)>,
263	
264	    /// Threads parked between logical process exit and a backend's final
265	    /// physical-exit report.
266	    pub physical_child_waiters: BTreeMap<DetPid, BTreeSet<DetTid>>,
267	
268	    /// Waiters whose deterministic physical-exit handoff is ready to commit.
269	    pub physical_child_ready: BTreeSet<DetTid>,
270	
271	    /// Blockers on external IO that are in the middle of executing (or have finished) and
272	    /// are waiting for permission from the scheduler to resume.
273	    ///
274	    /// The protocol here is that the `(request,response)` pair (in `next_turns`) for
275	    /// threads in `external_io_blockers` will have the request filled in with an
276	    /// `BlockedExternalContinue` request when the thread is past its blocking action and
277	    /// waiting for permission to resume. A failed operation governed by `BlockingVfork` instead
278	    /// reports `VforkFailed`, which follows the same re-admission path after cancelling its
279	    /// barrier. The request will stay empty while the thread is doing the blocking action. This is
280	    /// different than the normal relationship
281	    pub external_io_blockers: BTreeMap<DetTid, ExternalOpId>,
282	
283	    /// Threads executing the real `rt_sigsuspend` outside the runnable set.
284	    /// These retain the kernel's atomic temporary-mask semantics, but unlike
285	    /// arbitrary external IO they cannot complete without a signal.
286	    pub rt_sigsuspend_blockers: BTreeMap<DetTid, ExternalOpId>,
287	
288	    /// Parents parked awaiting deterministic delivery of a host-async `SIGCHLD`.
289	    ///
290	    /// When a guest child process exits, the kernel raises `SIGCHLD` on the
291	    /// parent at a moment decided purely by host timing. If the resulting
292	    /// `InboundSignal` turn is committed as soon as it arrives, its position
293	    /// races whatever guest work was already runnable -- classically a `make -jN`
294	    /// jobserver `pselect6` continuation -- and `--strict --verify` diverges.
295	    ///
296	    /// Instead the parent is parked here, out of the run queue, and re-admitted
297	    /// by `step2e_process_signal_deferred` only once no ordinary (non-poller)
298	    /// guest work remains: the same deterministic-work-first policy that governs
299	    /// `external_io_blockers`. The physical signal has already been delivered by
300	    /// the kernel, so the handler's `wait4`/`waitpid` still reaps a real host
301	    /// zombie and no synthetic signal is ever generated.
302	    pub sigchld_deferred: BTreeSet<DetTid>,
303	
304	    /// Deferred `SIGCHLD` parents that `step2e_process_signal_deferred` has
305	    /// re-admitted to the run queue. Their `InboundSignal` turn must now be
306	    /// granted rather than deferred again on the turn the scheduler selects them.
307	    pub sigchld_ready: BTreeSet<DetTid>,
308	}
