1981	    /// Try to pop the next event from the sorted list of stacktrace_events, if it matches the given
1982	    /// index.  This is idempotent, because subsequent attempts will just fizzle.
1983	    fn try_pop_stacktrace_event(
1984	        &mut self,
1985	        current_ix: u64,
1986	        observed: &SchedEvent,
1987	    ) -> MaybePrintStack {
1988	        let mut result = None;
1989	        if let Some(iter) = &mut self.stacktrace_events
1990	            && let Some((next_ix, event, m_path)) = iter.peek()
1991	        {
1992	            let go = if let Some(ev) = event {
1993	                (*next_ix == current_ix && events_consistent(observed, ev))
1994	                    || events_match(observed, ev)
1995	            } else {
1996	                *next_ix == current_ix
1997	            };
1998	            if go {
1999	                info!(
2000	                    "Now output stack trace for scheduled event #{} = {}:",
2001	                    current_ix, observed,
2002	                );
2003	                if m_path.is_none() {
2004	                    eprintln!(
2005	                        "\nPrinting stack trace for scheduled event #{} = {}:",
2006	                        current_ix, observed,
2007	                    );
2008	                }
2009	                result = Some(m_path.clone());
2010	                let _ = iter.next();
2011	            }
2012	        }
2013	        result
2014	    }
