2754	                remove.then_some(*parent)
2755	            })
2756	            .collect();
2757	        for parent in completed_parents {
2758	            self.vfork_barriers.remove(&parent);
2759	        }
2760	
2761	        if self.vfork_barriers.values().all(Option::is_some) {
2762	            Ok(())
2763	        } else {
