3791	                // grant the sleep as a `ResumeStatus::Normal` wake, which is exactly
3792	                // the internal violation `Detcore::handle_pause` refuses to accept.
3793	                let next_deadline = self
3794	                    .blocked
3795	                    .timed_waiters
3796	                    .next_deadline()
3797	                    .expect("internal error: no timed events found");
3798	                if next_deadline.is_indefinite() {
3799	                    if !external_waits_empty {
3800	                        // Blocking external IO may still complete and produce the
3801	                        // signal/wake the indefinite waiter needs, so this is not a
3802	                        // deadlock yet. Spin as step2c does for the same reason.
3803	                        trace!(
3804	                            "[scheduler] empty run-queue with only indefinite waiters, but external IO is outstanding for dtids {:?}. SPINNING!",
3805	                            &self.blocked.external_io_blockers
3806	                        );
3807	                        std::thread::yield_now();
3808	                        return Err(SkipTurn);
3809	                    }
3810	                    return Err(self.report_terminal_deadlock());
3811	                }
3812	                debug!(
3813	                    "[scheduler] Deadlock avoidance! Empty run-queue, so waking next timed event."
3814	                );
3815	                let (event_ns, evt) = self
3816	                    .blocked
3817	                    .timed_waiters
3818	                    .pop()
3819	                    .expect("internal error: no timed events found");
3820	                debug_assert_eq!(event_ns, next_deadline);
3821	                {
3822	                    let mut gt = global_time.lock().unwrap();
3823	                    let gt_now_ns = gt.as_nanos();
3824	                    if event_ns > gt_now_ns {
3825	                        info!("[scheduler] Skipping global time ahead to {}.", event_ns);
3826	                        let delta = event_ns.duration_since(gt_now_ns);
3827	                        detlog_debug!(
3828	                            "[sched] add extra global time for deadlock avoidance {:?} on current time {}",
3829	                            delta,
3830	                            gt_now_ns,
3831	                        );
3832	                        gt.add_extra_time(delta);
3833	                    } else {
3834	                        // A control hook may have crossed this deadline after
3835	                        // maintenance consumed its one event. Keep the separate
3836	                        // empty-queue wake/SkipTurn, without rewinding the clock.
3837	                        info!(
3838	                            "[scheduler] Waking elapsed timed event at {} with global time {} unchanged.",
3839	                            event_ns, gt_now_ns,
3840	                        );
3841	                    }
3842	                }
3843	
3844	                match evt {
3845	                    TimedEvent::ThreadEvt(dtid) => self.wake_timed_event(event_ns, dtid),
3846	                    TimedEvent::SignalEvt(id, dtid, sig) => {
3847	                        self.dispatch_timed_signal(event_ns, id, dtid, sig, false)
3848	                    }
3849	                }
3850	                return Err(SkipTurn);
3851	            }
3852	        }
3853	        Ok(())
3854	    }
