4045	    /// Helper function. Same postcondition as step4_resource_block
4046	    fn block_for_one_resource(
4047	        &mut self,
4048	        dettid: DetTid,
4049	        rid: &ResourceID,
4050	        _perm: &Permission,
4051	        signal_interrupt_errno: Option<i32>,
4052	        resp: &Ivar<SchedResponse>,
4053	    ) -> Result<(), SkipTurn> {
4054	        match rid {
4055	            ResourceID::SleepUntil(target_ns) => {
4056	                if *target_ns <= self.committed_time {
4057	                    trace!(
4058	                        "[dtid {}] time-based action ready to execute, target time {} is before committed global time {}",
4059	                        dettid, target_ns, self.committed_time
4060	                    );
4061	                    Ok(())
4062	                } else {
4063	                    trace!(
4064	                        "[dtid {}] time-based action not ready yet, registering waiter at future time {}. Current time is {}",
4065	                        dettid, target_ns, self.committed_time
4066	                    );
4067	                    info!(
4068	                        "[scheduler] >>>>>>>\n\n NONCOMMIT turn {}, SKIP dettid {} which wanted resource {:?} (blocking)",
4069	                        self.turn, dettid, rid
4070	                    );
4071	                    self.blocked.timed_waiters.insert(*target_ns, dettid);
4072	                    self.skip_turn_blocked(dettid)
4073	                }
4074	            }
4075	
4076	            // Thread BEGINS a blocking syscall outside the runnable set.
4077	            ResourceID::BlockingExternalIO(op_id)
4078	            | ResourceID::BlockingVfork(op_id)
4079	            | ResourceID::BlockingRtSigsuspend(op_id) => {
4080	                if matches!(rid, ResourceID::BlockingVfork(_)) {
4081	                    assert!(self.vfork_barriers.insert(dettid, None).is_none());
4082	                }
4083	                if enabled!(Level::INFO) {
4084	                    let record_suffix = scheduler_commit_record_suffix(
4085	                        self.turn,
4086	                        self.committed_time.as_nanos(),
4087	                        false,
4088	                        false,
4089	                    );
4090	                    info!(
4091	                        "[scheduler] >>>>>>>\n\n COMMIT turn {}, BACKGROUND dettid {} (maybe-blocking){}",
4092	                        self.turn, dettid, record_suffix
4093	                    );
4094	                }
4095	                // Here we allow the action to execute asynchrounously, in the
4096	                // background. The protocol is that it must:
4097	                //   (1) not interfere with other internal/external actions (independence),
4098	                //   (2) Request a BlockedExternalContinue as the first thing after the external IO is complete.
4099	                self.run_queue.undo_tentative_pop(); // Begun in step3
4100	                assert!(self.run_queue.remove_tid(dettid)); // Deschedule while in background.
4101	
4102	                // TODO: Register the action that is occuring in the background:
4103	                // let act = self.new_action(Ivar::new());
4104	                // self.bg_action_pool.insert(act.action_id, act);
4105	
4106	                // Unblock guest so that potentially-blocking IO action can get
4107	                // started. This intentionally races with subsequent turns the
4108	                // scheduler commits, and thus it leans on an assumption of
4109	                // non-interference, or on interference *only* affecting the external
4110	                // actions that will be recorded anyway.
4111	                self.run_queue.consume_yield_exclusion();
4112	                self.unblock_guest(dettid, resp)?;
4113	
4114	                // Only once the ivars are cleared and the guest is ready to issue
4115	                // BlockedExternalContinue do we record which blocked pool owns it.
4116	                let old = if matches!(rid, ResourceID::BlockingRtSigsuspend(_)) {
4117	                    self.blocked.rt_sigsuspend_blockers.insert(dettid, *op_id)
4118	                } else {
4119	                    self.blocked.external_io_blockers.insert(dettid, *op_id)
4120	                };
4121	                assert!(old.is_none(), "thread started a second external operation");
4122	                Err(SkipTurn)
4123	            }
4124	
4125	            // Thread CONTINUES after completing [potentially] blocking IO.
4126	            ResourceID::BlockedExternalContinue(_) | ResourceID::VforkFailed(_) => {
4127	                // We leave the thread out of the run-queue.  At the point we put it back
4128	                // in, this resource request is immediately granted.
4129	                Ok(())
4130	            }
4131	
4132	            ResourceID::WaitChild { parent, spec } => {
4133	                if self.ready_child_wait(*parent, *spec).is_some()
4134	                    || !self.has_child_wait_target(*parent, *spec)
4135	                {
4136	                    Ok(())
4137	                } else {
4138	                    info!(
4139	                        "[scheduler] NONCOMMIT turn {}, parking dettid {} for child {:?}",
4140	                        self.turn, dettid, spec
4141	                    );
4142	                    assert!(
4143	                        self.blocked
4144	                            .child_waiters
4145	                            .insert(dettid, (*parent, *spec))
4146	                            .is_none()
4147	                    );
4148	                    self.skip_turn_blocked(dettid)
4149	                }
4150	            }
4151	
4152	            ResourceID::WaitPhysicalChild(child) => {
4153	                if self.blocked.physical_child_ready.remove(&dettid) {
4154	                    Ok(())
4155	                } else {
4156	                    info!(
4157	                        "[scheduler] NONCOMMIT turn {}, parking dettid {} for physical child {}",
4158	                        self.turn, dettid, child
4159	                    );
4160	                    let completion_already_observed =
4161	                        self.completed_physical_process_exits.contains(child);
4162	                    assert!(
4163	                        self.blocked
4164	                            .physical_child_waiters
4165	                            .entry(*child)
4166	                            .or_default()
4167	                            .insert(dettid)
4168	                    );
4169	                    let skipped = self.skip_turn_blocked(dettid);
4170	                    if completion_already_observed {
4171	                        self.wake_physical_child_waiters(*child);
4172	                    }
4173	                    skipped
4174	                }
4175	            }
4176	
4177	            // Thread requests change in priority
4178	            ResourceID::PriorityChangePoint(prio, change_time, rcbs, epochs) => {
4179	                self.perform_priority_changepoint(dettid, *prio, *change_time, *rcbs, epochs)
4180	            }
4181	
4182	            // For now, all other resource types are immediately granted.
4183	            // (TODO/FIXME: handle the entire set of resource requests.)
4184	            ResourceID::FileContents(_) => Ok(()),
4185	            ResourceID::FileMetadata(_) => Ok(()),
4186	            ResourceID::DirectoryContents(_) => Ok(()),
4187	            ResourceID::MemAddrSpace(_) => Ok(()),
4188	            ResourceID::Path(_) => Ok(()),
4189	            ResourceID::PathsTransitive(_) => Ok(()),
4190	            ResourceID::Device(_) => Ok(()),
4191	            // The scheduler-ordered `Exit` grant is the deterministic moment a
4192	            // child process leaves the run set. Register a one-shot child-exit
4193	            // `SIGCHLD` for the reaping parent, to be delivered at a deterministic
4194	            // logical time by `step2b_process_timed`, instead of relying on the
4195	            // host-async kernel `SIGCHLD` whose arrival time is host-timed (the
4196	            // `make -jN` / redis `--strict --verify` nondeterminism source).
4197	            // A backend that registered a PIDFD_THREAD already preserves the
4198	            // kernel's native child-exit signal. Sending another SIGCHLD through
4199	            // that pidfd would make the application observe both CLD_EXITED and
4200	            // SI_TKILL for one child, so only the scheduler wait readiness is
4201	            // synthesized on that path.
4202	            ResourceID::Exit { group, process, .. } => {
4203	                if *group
4204	                    && let Some(parent) = self.thread_tree.parent_process(process)
4205	                    && self.should_synthesize_child_exit_signal(parent)
4206	                {
4207	                    // Fire strictly after the current committed time so the event
4208	                    // is dispatched on a subsequent scheduler pass (DetTid == DetPid
4209	                    // for a group leader, so `parent` is also the parent thread id).
4210	                    let deadline = self.committed_time + LogicalTime::from_nanos(1);
4211	                    self.blocked
4212	                        .timed_waiters
4213	                        .insert_child_exit(deadline, *process, parent, parent);
4214	                }
4215	                Ok(())
4216	            }
4217	            ResourceID::ParentContinue { .. } => Ok(()),
4218	            ResourceID::InternalIOPolling => Ok(()),
4219	            ResourceID::FutexWait => Ok(()),
4220	            ResourceID::TraceReplay => Ok(()),
4221	            ResourceID::SchedYield => Ok(()),
4222	
4223	            // A guest thread checking in at a happens-before anchor point. Delegate
4224	            // to the enforcement logic, which either grants passage (firing anchors)
4225	            // or parks the thread until its gating BEFORE anchor fires.
4226	            ResourceID::HappensBeforeCheckpoint(count) => self.hb_checkpoint(dettid, *count),
4227	
4228	            // A host-async SIGCHLD (a guest child process exited) is delivered to
4229	            // the parent at a moment decided by host timing. Committing that turn
4230	            // immediately makes the signal race whatever guest work was already
4231	            // runnable (e.g. a `make -jN` jobserver `pselect6` continuation),
4232	            // which diverges under `--strict --verify`. Defer it deterministic-
4233	            // work-first: park the parent out of the run queue and let
4234	            // `step2e_process_signal_deferred` re-admit it once no ordinary guest
4235	            // work remains, mirroring the `external_io_blockers` policy. Signals
4236	            // that the scheduler itself synthesizes deterministically (timers via
4237	            // `fire_alarm`) are never SIGCHLD and are unaffected.
4238	            ResourceID::WaitidSignals(_) => Ok(()),
4239	            ResourceID::InboundSignal(sig) => {
4240	                // `sigchld_ready` marks a parent step2e has already re-admitted;
4241	                // grant it now rather than deferring it a second time.
4242	                let already_readmitted = self.blocked.sigchld_ready.remove(&dettid);
4243	                if sig.signal() == Some(Signal::SIGCHLD)
4244	                    && signal_interrupt_errno.is_none()
4245	                    && !already_readmitted
4246	                    && self.run_queue.has_runnable_besides(dettid)
4247	                {
4248	                    self.run_queue.undo_tentative_pop(); // Begun in step3.
4249	                    assert!(self.run_queue.remove_tid(dettid));
4250	                    self.blocked.sigchld_deferred.insert(dettid);
4251	                    Err(SkipTurn)
4252	                } else {
4253	                    Ok(())
4254	                }
4255	            }
4256	        }
4257	    }
