4321	        }
4322	
4323	        let popped = self.run_queue.commit_tentative_pop(); // Begun in step3.
4324	        assert_eq!(dettid, popped);
4325	        self.runqueue_push_back(dettid); // Repush with new priority
4326	        trace!(
4327	            "[dettid {}] changepoint: Priority mapping after change to priority {}: {:?}",
4328	            dettid, new_priority, self.priorities
4329	        );
4330	
4331	        // Update request to be empty so the thread is unconditionally
4332	        // runnable when it next comes up in the queue.
4333	        let empty_req = Ivar::full(Ok(Resources::new(dettid)));
4334	        trace!(
4335	            "[dettid {}] Priority change point emplaced empty resource request at new {}",
4336	            dettid, empty_req
4337	        );
4338	        self.next_turns
4339	            .get_mut(&dettid)
4340	            .expect("nextturn present")
4341	            .req = empty_req;
4342	        info!(
4343	            "[scheduler] >>>>>>>\n\n NONCOMMIT turn {}, dettid {} changed priority to {}",
4344	            self.turn, dettid, new_priority
4345	        );
