4613	        // merged `WaitidSignals` batch. Sort then dedup so the reported set is a
4614	        // canonical function of WHICH signals are pending, not of how many
4615	        // resources happen to carry each one or of the order they arrived in.
4616	        signals.sort_by_key(|signal| signal.0 as libc::c_int);
4617	        signals.dedup_by_key(|signal| signal.0 as libc::c_int);
