4837	    /// Resolve an [`AdmitIntent`] to a concrete [`AdmitSide`], consuming the
4838	    /// post-fork PRNG draw for `RunsPostFork::Random`.
4839	    ///
4840	    /// Called at the drain rather than in the handler, so the draw is never
4841	    /// consumed in host *RPC arrival* order, and the draws taken within one
4842	    /// drain follow canonical `DetTid` order. This function only canonicalizes
4843	    /// draws within a fixed drain; each admission site must separately bind its
4844	    /// drain membership to deterministic scheduler state. See
4845	    /// [`Scheduler::admit_to_run_queue`] for the causal and explicit barriers
4846	    /// that provide that binding for all current production sites.
4847	    fn resolve_admit_intent(&mut self, intent: AdmitIntent) -> AdmitSide {
4848	        match intent {
4849	            AdmitIntent::Fixed(side) => side,
4850	            AdmitIntent::PostFork(mode) => {
4851	                if self.child_runs_first_post_fork(mode) {
4852	                    AdmitSide::Front
4853	                } else {
4854	                    AdmitSide::Back
4855	                }
4856	            }
4857	        }
4858	    }
