4885	    /// Apply queued cross-task signal notifications at the deterministic
4886	    /// run-queue mutation point. Re-check the request because a target may have
4887	    /// exited or completed its wait before this drain.
4888	    fn drain_pending_cross_task_signals(&mut self) {
4889	        let pending = std::mem::take(&mut self.pending_cross_task_signals);
4890	        for (dettid, mut signals) in pending {
4891	            match self.waitid_signal_request(dettid) {
4892	                Some(WaitidSignalRequest::Parked) => {
4893	                    // Decide run-queue residency HERE, by asking the queue, and
4894	                    // never by inferring it from which resource the thread
4895	                    // holds. A thread can hold either park request while already
4896	                    // queued: `wake_child_waiters` re-admits a waiter without
4897	                    // clearing its `WaitChild` request, and `step6_reenqueue`
4898	                    // pushes a completed turn back before the guest issues its
4899	                    // next request. `force_unblock_thread` ends in
4900	                    // `runqueue_push_*`, so pushing an already-queued thread
4901	                    // trips the run-queue invariant under `debug_assertions`
4902	                    // and, worse, SILENTLY double-enqueues in release — one
4903	                    // thread selected twice. This mirrors `wake_signaled_guest`,
4904	                    // which likewise consults `thread_status` before removing.
4905	                    if self.run_queue.contains_tid(dettid) {
4906	                        let removed = self.run_queue.remove_tid(dettid);
4907	                        debug_assert!(
4908	                            removed,
4909	                            "run_queue.contains_tid disagreed with remove_tid for {dettid}"
4910	                        );
4911	                    }
4912	                    signals.sort_by_key(SigWrapper::raw);
4913	                    signals.dedup();
4914	                    let mut resources = Resources::new(dettid);
4915	                    resources.insert(ResourceID::WaitidSignals(signals), Permission::W);
4916	                    self.force_unblock_thread(dettid, resources);
4917	                }
4918	                Some(WaitidSignalRequest::Pending(existing)) => {
4919	                    signals.extend(existing);
4920	                    signals.sort_by_key(SigWrapper::raw);
4921	                    signals.dedup();
4922	                    // One resource, always. `step4_resource_block` and
4923	                    // `blocking_request_is_ready` both assert a request carries
4924	                    // exactly one, so this must replace the request rather than
4925	                    // add to it. Only a request whose sole resource is already
4926	                    // `WaitidSignals` reaches here, so nothing is discarded.
4927	                    let mut resources = Resources::new(dettid);
4928	                    resources.insert(ResourceID::WaitidSignals(signals), Permission::W);
4929	                    let Some(next_turn) = self.next_turns.get_mut(&dettid) else {
4930	                        continue;
4931	                    };
4932	                    next_turn.req = Ivar::full(Ok(resources));
4933	                }
4934	                None => {
4935	                    let Some(existing) = self.restartable_internal_io_signals(dettid) else {
4936	                        continue;
4937	                    };
4938	                    // ERESTARTSYS is the existing contract by which the kernel
4939	                    // decides whether this physically pending signal is
4940	                    // blocked, ignored, restarts the syscall, or interrupts it
4941	                    // for a handler. Replace the polling request rather than
4942	                    // adding a second resource; step4 accepts exactly one.
4943	                    if self.run_queue.contains_tid(dettid) {
4944	                        let removed = self.run_queue.remove_tid(dettid);
4945	                        debug_assert!(
4946	                            removed,
4947	                            "run_queue.contains_tid disagreed with remove_tid for {dettid}"
4948	                        );
4949	                    }
4950	                    signals.extend(existing);
4951	                    signals.sort_by_key(SigWrapper::raw);
4952	                    signals.dedup();
4953	                    if signals.is_empty() {
4954	                        continue;
4955	                    }
4956	                    let mut resources = Resources::new(dettid);
4957	                    // `WaitidSignals` is already the scheduler's one-resource
4958	                    // representation for a complete signal identity set. The
4959	                    // ERESTARTSYS marker distinguishes this write wakeup from a
4960	                    // waitid request and survives later notification batches.
4961	                    resources.insert(ResourceID::WaitidSignals(signals), Permission::W);
4962	                    resources.set_signal_interrupt_errno(Errno::ERESTARTSYS);
4963	                    self.force_unblock_thread(dettid, resources);
4964	                }
4965	            }
4966	        }
4967	    }
