5029	    /// Drain admissions deferred by [`Scheduler::admit_to_run_queue`] into the
5030	    /// run queue at a single deterministic point: the very start of `step2`,
5031	    /// before `step3_peek` opens a tentative window (so `tentative_selection` is
5032	    /// guaranteed `None` here). Draining a `BTreeMap` visits `DetTid`s in sorted
5033	    /// order, so the resulting run-queue state is a pure function of the
5034	    /// deterministic schedule rather than of RPC/lock-acquisition timing.
5035	    fn drain_pending_run_queue_admissions(&mut self) {
5036	        if self.pending_run_queue_admissions.is_empty() {
5037	            return;
5038	        }
5039	        let pending = std::mem::take(&mut self.pending_run_queue_admissions);
5040	        // `pending` is a `BTreeMap`, so iteration visits `DetTid`s in sorted
5041	        // order. Resolving each intent here (rather than at the racing handler)
5042	        // means any `RunsPostFork::Random` PRNG draw is consumed in this
5043	        // canonical order, so both the admission order *and* the chosen side are
5044	        // pure functions of deterministic state.
5045	        for (dtid, intent) in pending {
5046	            // A thread retired (exec/kill) between record and drain is skipped.
5047	            // `remove_blocking_entries` also clears the buffer on teardown, so
5048	            // this guard is defensive against any teardown path that does not.
5049	            if !self.next_turns.contains_key(&dtid) {
5050	                trace!(
5051	                    "[step2] skipping deferred admission of retired thread {:?}",
5052	                    dtid
5053	                );
5054	                continue;
5055	            }
5056	            let side = self.resolve_admit_intent(intent);
5057	            self.admit_now(dtid, side);
5058	        }
5059	    }
