6567	    /// F7 (adjacent-snapshot sensitivity): this fixture directly places two
6568	    /// admissions in adjacent step2 drains; it does not model a production
6569	    /// handler protocol. Every current asynchronous admission site separately
6570	    /// fixes snapshot membership: ordinary clone buffers before the parent's
6571	    /// `ParentContinue`, `vfork` uses its registration barrier, and exec
6572	    /// reconnect buffers before retiring and resolving the caller request. See
6573	    /// [`Scheduler::admit_to_run_queue`] for those causal bindings.
6574	    ///
6575	    /// The synthetic split remains a negative/sensitivity bracket for that
6576	    /// requirement. Replaying one fixed split at one seed is reproducible, but
6577	    /// swapping which child occupies the first drain changes the resolved queue
6578	    /// order. Thus a future unanchored admission site would make host-selected
6579	    /// membership observable; this test must not be read as evidence that any
6580	    /// current production site is unanchored.
6581	    #[test]
6582	    fn deferred_admission_binds_to_snapshot_membership_across_adjacent_drains() {
6583	        let config = Config {
6584	            sched_seed: Some(0x5107),
6585	            runs_post_fork: RunsPostFork::Random,
6586	            ..Default::default()
6587	        };
6588	        let anchor = DetTid::from_raw(3);
6589	        let a = DetTid::from_raw(31);
6590	        let b = DetTid::from_raw(37);
6591	
6592	        // Admit `first` in drain 1 and `second` in drain 2 (two adjacent step2
6593	        // drains) and return the final run-queue order relative to a fixed
6594	        // anchor, which encodes each child's resolved front/back side.
6595	        let split = |first: DetTid, second: DetTid| -> Vec<DetTid> {
6596	            let mut sched = Scheduler::new(&config);
6597	            register_known_thread(&mut sched, anchor);
6598	            register_known_thread(&mut sched, a);
6599	            register_known_thread(&mut sched, b);
6600	            sched.runqueue_push_back(anchor);
6601	
6602	            sched.admit_to_run_queue(first, AdmitIntent::PostFork(RunsPostFork::Random));
6603	            sched.drain_pending_run_queue_admissions(); // drain 1
6604	            sched.admit_to_run_queue(second, AdmitIntent::PostFork(RunsPostFork::Random));
6605	            sched.drain_pending_run_queue_admissions(); // drain 2 (adjacent)
6606	
6607	            sched.run_queue.tids().copied().collect()
6608	        };
6609	
6610	        // Fixed synthetic membership is deterministic across identical replays.
6611	        let canonical = split(a, b);
6612	        assert_eq!(
6613	            canonical,
6614	            split(a, b),
6615	            "identical schedule -> identical result"
6616	        );
6617	        assert!(canonical.contains(&a) && canonical.contains(&b) && canonical.contains(&anchor));
6618	
6619	        // Sensitivity control: changing synthetic snapshot membership changes
6620	        // the outcome for this seed, so a missing production anchor would be
6621	        // observable rather than inert.
6622	        assert_ne!(
6623	            split(a, b),
6624	            split(b, a),
6625	            "swapping snapshot membership changes the resolved order"
6626	        );
6627	    }
