7152	        // The shape that crashed: an ordinary delivered signal, nothing to do
7153	        // with waitid.
7154	        let mut inbound = Resources::new(target);
7155	        inbound.insert(
7156	            ResourceID::InboundSignal(SigWrapper::from(Signal::SIGUSR1)),
7157	            Permission::W,
7158	        );
7159	        scheduler.next_turns.get_mut(&target).unwrap().req = Ivar::full(Ok(inbound));
7160	        scheduler.runqueue_push_back(target);
7161	
7162	        scheduler.notify_signal_pending(target, SigWrapper::from(Signal::SIGUSR2));
7163	        scheduler.drain_pending_cross_task_signals();
7164	
7165	        let resources = scheduler
7166	            .next_turns
7167	            .get(&target)
7168	            .and_then(|next_turn| next_turn.req.try_read())
7169	            .and_then(Result::ok)
7170	            .expect("the target should still hold a request");
7171	        assert!(
7172	            resources.resources.len() <= 1,
7173	            "the drain produced a {}-resource request, which step4 asserts against: {:?}",
