                ..Default::default()
            },
            reverie::ChildExitPublicationEffect::Queued,
            true,
        ),
    ] {
        let parent = executor();
        parent
            .state
            .process_signals
            .lock()
            .unwrap()
            .dispositions
            .insert(libc::SIGCHLD, action);

